#![cfg(not(any(feature="cuda-11040",feature="cuda-11050",feature="cuda-11060",feature="cuda-11070",feature="cuda-11080")))]
use super::{lifetime_event_cleanup_tests::seams as events,lifetime_stream_cleanup_tests::seams as streams,lifetime_slice_cleanup_tests::seams as memory};
use crate::driver::{result::context_test_seams,sys,CudaContext,CudaEvent,CudaStream,DriverError,PrimaryContextLifetime,PrimaryContextLossCause};
use std::sync::Arc;
#[derive(Clone,Copy,Debug)]
enum Boundary{EventCreate,EventRecord,EventQuery,ContextSync,StreamCreate,StreamSync,StreamWait,SliceAlloc}
const ALL:[Boundary;8]=[Boundary::EventCreate,Boundary::EventRecord,Boundary::EventQuery,Boundary::ContextSync,Boundary::StreamCreate,Boundary::StreamSync,Boundary::StreamWait,Boundary::SliceAlloc];
fn fault(op:Boundary,e:&events::Guard,s:&streams::Guard,m:&memory::Guard,error:Option<sys::CUresult>){match op{Boundary::EventCreate=>e.set_create_error(error),Boundary::EventRecord=>e.set_record_error(error),Boundary::EventQuery=>e.set_query_error(error),Boundary::ContextSync=>s.set_context_synchronize_error(error),Boundary::StreamCreate=>s.set_create_error(error),Boundary::StreamSync=>m.set_synchronize_error(error),Boundary::StreamWait=>s.set_wait_error(error),Boundary::SliceAlloc=>m.set_allocate_error(error)}}
fn run(op:Boundary,ctx:&Arc<CudaContext>,stream:&Arc<CudaStream>,event:&CudaEvent)->Result<(),DriverError>{match op{Boundary::EventCreate=>ctx.new_event(None).map(drop),Boundary::EventRecord=>event.record(stream),Boundary::EventQuery=>event.try_is_complete().map(drop),Boundary::ContextSync|Boundary::StreamCreate=>ctx.new_stream().map(drop),Boundary::StreamSync=>stream.synchronize(),Boundary::StreamWait=>stream.wait(event),Boundary::SliceAlloc=>unsafe{stream.alloc::<u8>(16)}.map(drop)}}
fn calls(e:&events::Guard,s:&streams::Guard,m:&memory::Guard)->[usize;12]{let e=e.snapshot();let s=s.snapshot();let m=m.snapshot();[e.create_attempts,e.destroyed,e.queried,e.recorded,e.synchronized,s.create_attempts,s.destroyed,s.context_synchronizes,s.waits,m.allocation_attempts,m.stream_synchronizes,m.async_frees+m.sync_frees]}
fn native_terminal(op:Boundary,error:sys::CUresult){
    for asynchronous in if matches!(op,Boundary::SliceAlloc){vec![false,true]}else{vec![true]}{
        let driver=context_test_seams::Guard::new();let e=events::Guard::new();let s=streams::Guard::new();let m=memory::Guard::new();let life=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let mut ctx=CudaContext::new_tracked(Arc::clone(&life)).map_err(|e|e.0 as u32).unwrap();Arc::get_mut(&mut ctx).unwrap().has_async_alloc=asynchronous;let sibling=CudaContext::new_tracked(Arc::clone(&life)).map_err(|e|e.0 as u32).unwrap();let stream=ctx.default_stream();let event=ctx.new_event(None).map_err(|e|e.0 as u32).unwrap();fault(op,&e,&s,&m,Some(error));
        let result=run(op,&ctx,&stream,&event).map_err(|e|e.0 as u32);fault(op,&e,&s,&m,None);assert_eq!(result,Err(error as u32),"actual native {op:?} result must be returned");assert_eq!(life.loss().map(|loss|(loss.recorded_id,loss.observed_id,loss.cause)),Some((17,None,PrimaryContextLossCause::DriverStatus(error))),"actual native {op:?} must publish before handoff");let first=life.loss();let before=driver.snapshot();let native=calls(&e,&s,&m);
        assert_eq!(ctx.check_err().map_err(|e|e.0 as u32),Err(error as u32));assert_eq!(ctx.check_err().map_err(|e|e.0 as u32),Err(error as u32));assert_eq!(sibling.bind_to_thread().map_err(|e|e.0 as u32),Err(error as u32));assert_eq!(run(op,&ctx,&stream,&event).map_err(|e|e.0 as u32),Err(error as u32));sibling.record_err::<()>(Err(DriverError(sys::CUresult::CUDA_ERROR_OUT_OF_MEMORY)));assert_eq!(life.loss(),first);assert_eq!(sibling.check_err().map_err(|e|e.0 as u32),Err(error as u32));drop(event);drop(stream);drop(ctx);drop(sibling);let after=driver.snapshot();assert_eq!((after.primary_queries,after.id_queries,after.queries,after.binds),(before.primary_queries,before.id_queries,before.queries,before.binds));assert_eq!(calls(&e,&s,&m),native);drop(life);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));
    }
}
#[test]fn actual_event_create_201_is_terminal_before_handoff(){native_terminal(Boundary::EventCreate,sys::CUresult::CUDA_ERROR_INVALID_CONTEXT);}
#[test]fn actual_event_record_201_is_terminal_before_handoff(){native_terminal(Boundary::EventRecord,sys::CUresult::CUDA_ERROR_INVALID_CONTEXT);}
#[test]fn actual_event_query_201_is_terminal_before_handoff(){native_terminal(Boundary::EventQuery,sys::CUresult::CUDA_ERROR_INVALID_CONTEXT);}
#[test]fn actual_stream_constructor_sync_201_is_terminal_before_handoff(){native_terminal(Boundary::ContextSync,sys::CUresult::CUDA_ERROR_INVALID_CONTEXT);}
#[test]fn actual_stream_create_201_is_terminal_before_handoff(){native_terminal(Boundary::StreamCreate,sys::CUresult::CUDA_ERROR_INVALID_CONTEXT);}
#[test]fn actual_stream_sync_201_is_terminal_before_handoff(){native_terminal(Boundary::StreamSync,sys::CUresult::CUDA_ERROR_INVALID_CONTEXT);}
#[test]fn actual_stream_wait_201_is_terminal_before_handoff(){native_terminal(Boundary::StreamWait,sys::CUresult::CUDA_ERROR_INVALID_CONTEXT);}
#[test]fn actual_slice_alloc_201_is_terminal_before_child_construction(){native_terminal(Boundary::SliceAlloc,sys::CUresult::CUDA_ERROR_INVALID_CONTEXT);}
#[test]fn actual_native_709_keeps_its_existing_origin_contract(){for op in ALL{native_terminal(op,sys::CUresult::CUDA_ERROR_CONTEXT_IS_DESTROYED);}}
#[test]fn ordinary_operation_oom_preserves_retry_without_delayed_error(){
    for op in ALL{let driver=context_test_seams::Guard::new();let e=events::Guard::new();let s=streams::Guard::new();let m=memory::Guard::new();let life=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let ctx=CudaContext::new_tracked(Arc::clone(&life)).map_err(|e|e.0 as u32).unwrap();let stream=ctx.default_stream();let event=ctx.new_event(None).map_err(|e|e.0 as u32).unwrap();fault(op,&e,&s,&m,Some(sys::CUresult::CUDA_ERROR_OUT_OF_MEMORY));let result=run(op,&ctx,&stream,&event);fault(op,&e,&s,&m,None);assert_eq!(result.map_err(|e|e.0 as u32),Err(sys::CUresult::CUDA_ERROR_OUT_OF_MEMORY as u32));assert!(life.loss().is_none());assert_eq!(ctx.check_err().map_err(|e|e.0 as u32),Ok(()));assert_eq!(run(op,&ctx,&stream,&event).map_err(|e|e.0 as u32),Ok(()));assert!(life.loss().is_none());drop(event);drop(stream);drop(ctx);drop(life);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));}
}
#[test]fn untracked_native_201_keeps_the_legacy_return_and_retry_contract(){
    for op in ALL{let driver=context_test_seams::Guard::new();let e=events::Guard::new();let s=streams::Guard::new();let m=memory::Guard::new();let ctx=CudaContext::new(0).map_err(|e|e.0 as u32).unwrap();let stream=ctx.default_stream();let event=ctx.new_event(None).map_err(|e|e.0 as u32).unwrap();fault(op,&e,&s,&m,Some(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT));let result=run(op,&ctx,&stream,&event);fault(op,&e,&s,&m,None);assert_eq!(result.map_err(|e|e.0 as u32),Err(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT as u32));assert_eq!(ctx.check_err().map_err(|e|e.0 as u32),Ok(()));assert_eq!(run(op,&ctx,&stream,&event).map_err(|e|e.0 as u32),Ok(()));drop(event);drop(stream);drop(ctx);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));}
}
#[test]fn association_201_never_becomes_native_generation_loss(){
    let driver=context_test_seams::Guard::new();let e=events::Guard::new();let s=streams::Guard::new();let life=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let other=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let ctx=CudaContext::new_tracked(Arc::clone(&life)).map_err(|e|e.0 as u32).unwrap();let foreign=CudaContext::new_tracked(Arc::clone(&other)).map_err(|e|e.0 as u32).unwrap();assert_eq!(ctx.cu_ctx(),foreign.cu_ctx());let untracked=CudaContext::new(0).map_err(|e|e.0 as u32).unwrap();let stream=ctx.default_stream();let event=foreign.new_event(None).map_err(|e|e.0 as u32).unwrap();let legacy=untracked.new_event(None).map_err(|e|e.0 as u32).unwrap();let before=driver.snapshot();assert_eq!(event.record(&stream).map_err(|e|e.0 as u32),Err(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT as u32));assert_eq!(stream.wait(&legacy).map_err(|e|e.0 as u32),Err(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT as u32));assert_eq!((e.snapshot().recorded,s.snapshot().waits),(0,0));let after=driver.snapshot();assert_eq!((after.primary_queries,after.id_queries,after.queries,after.binds),(before.primary_queries,before.id_queries,before.queries,before.binds));assert!(life.loss().is_none());assert!(other.loss().is_none());assert_eq!(ctx.check_err().map_err(|e|e.0 as u32),Ok(()));drop(legacy);drop(event);drop(stream);drop(ctx);drop(foreign);drop(untracked);drop(life);drop(other);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(3,3));
}
#[test]fn actual_wait_201_publishes_to_both_distinct_healthy_lifetimes(){
    let driver=context_test_seams::Guard::new();let e=events::Guard::new();let s=streams::Guard::new();let life=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let other=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let ctx=CudaContext::new_tracked(Arc::clone(&life)).map_err(|e|e.0 as u32).unwrap();let foreign=CudaContext::new_tracked(Arc::clone(&other)).map_err(|e|e.0 as u32).unwrap();let stream=ctx.default_stream();let event=foreign.new_event(None).map_err(|e|e.0 as u32).unwrap();s.set_wait_error(Some(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT));let result=stream.wait(&event);s.set_wait_error(None);assert_eq!(result.map_err(|e|e.0 as u32),Err(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT as u32));assert_eq!(s.snapshot().waits,1);for owner in [&life,&other]{assert_eq!(owner.loss().map(|loss|loss.cause),Some(PrimaryContextLossCause::DriverStatus(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT)));}let before=driver.snapshot();for context in [&ctx,&foreign]{assert_eq!(context.bind_to_thread().map_err(|e|e.0 as u32),Err(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT as u32));}assert_eq!(stream.wait(&event).map_err(|e|e.0 as u32),Err(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT as u32));assert_eq!(s.snapshot().waits,1);drop(event);assert_eq!(e.snapshot().destroyed,0);let after=driver.snapshot();assert_eq!((after.primary_queries,after.id_queries,after.queries,after.binds),(before.primary_queries,before.id_queries,before.queries,before.binds));drop(stream);drop(ctx);drop(foreign);drop(life);drop(other);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(2,2));
}
#[test]fn actual_private_pool_malloc_201_publishes_before_child_events(){
    let driver=context_test_seams::Guard::new();let e=events::Guard::new();let m=memory::Guard::new();let pools=super::tracked_pool_tests::seams::Guard::new();let _legacy=super::mem_pool::seams::Reset::new();super::mem_pool::seams::DRIVER_VERSION.set(Some(12060));let life=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let pool=Arc::new(crate::driver::CudaMemPool::create_tracked(Arc::clone(&life),&crate::driver::MemPoolProps{max_size:0,release_threshold:128}).map_err(|e|e.0 as u32).unwrap());let ctx=CudaContext::new_with_mem_pool_tracked(Arc::clone(&life),Arc::clone(&pool)).map_err(|e|e.0 as u32).unwrap();let stream=ctx.default_stream();m.set_allocate_error(Some(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT));let result=unsafe{stream.alloc::<u8>(16)};m.set_allocate_error(None);assert_eq!(result.map(drop).map_err(|e|e.0 as u32),Err(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT as u32));assert_eq!((pools.snapshot().allocations,m.snapshot().allocation_attempts,e.snapshot().create_attempts),(1,1,0));assert_eq!(life.loss().map(|loss|loss.cause),Some(PrimaryContextLossCause::DriverStatus(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT)));let before=driver.snapshot();assert_eq!(unsafe{stream.alloc::<u8>(16)}.map(drop).map_err(|e|e.0 as u32),Err(sys::CUresult::CUDA_ERROR_INVALID_CONTEXT as u32));assert_eq!((pools.snapshot().allocations,m.snapshot().allocation_attempts,e.snapshot().create_attempts),(1,1,0));drop(stream);drop(ctx);drop(pool);assert_eq!(pools.snapshot().destroy_attempts,0);let after=driver.snapshot();assert_eq!((after.primary_queries,after.id_queries,after.queries,after.binds),(before.primary_queries,before.id_queries,before.queries,before.binds));drop(life);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));
}
